//! Cross-repository proof that Base Worker artifacts execute in celld.
//!
//! The successful test is ignored because it deliberately requires an artifact
//! generated by a separately checked-out Base Worker fork. The proof script
//! builds that artifact and supplies `BASE_WORKER_ARTIFACT` explicitly.

use celld::engine_api::{Compat, WorkerConfigOptions};
use celld::js::{RequestBody, Worker, WorkerConfig};
use celld::runtime::StatelessRuntime;
use std::path::PathBuf;
use std::sync::{Arc, Once};

fn init_v8() {
    static INIT: Once = Once::new();
    INIT.call_once(celld::runtime::init_v8);
}

fn init_async_runtime() {
    static INIT: Once = Once::new();
    INIT.call_once(|| celld::asyncrt::set_host_handle(tokio::runtime::Handle::current()));
}

fn options(src: String) -> WorkerConfigOptions {
    WorkerConfigOptions {
        src,
        script_name: "base-worker-bridge".to_string(),
        do_classes: Vec::new(),
        bindings: Vec::new(),
        r2_bindings: Vec::new(),
        d1_bindings: Vec::new(),
        kv_bindings: Vec::new(),
        queue_bindings: Vec::new(),
        queue_consumers: Vec::new(),
        workflow_bindings: Vec::new(),
        vars: Vec::new(),
        node: "base-worker-bridge-node".to_string(),
        modules: Vec::new(),
        compat: Compat::default(),
    }
}

fn artifact_path() -> PathBuf {
    std::env::var_os("BASE_WORKER_ARTIFACT")
        .map(PathBuf::from)
        .expect("BASE_WORKER_ARTIFACT must point to a Base Worker-generated bundle")
}

#[tokio::test(flavor = "current_thread")]
#[ignore = "requires a Base Worker bundle; run scripts/prove-base-worker.sh"]
#[allow(
    clippy::disallowed_methods,
    reason = "The generated artifact is explicit cross-repository test input, not celld node storage."
)]
async fn base_worker_typescript_bundle_executes_through_celld_v8() {
    init_v8();
    init_async_runtime();

    let artifact = artifact_path();
    let source = std::fs::read_to_string(&artifact).unwrap_or_else(|error| {
        panic!("read Base Worker artifact {}: {error}", artifact.display())
    });

    assert!(
        source.contains("Hello from Base Worker"),
        "the bundled local TypeScript dependency is missing"
    );
    assert!(
        !source.contains("interface WorkerMessage"),
        "the artifact still contains TypeScript-only interface syntax"
    );

    let config = options(source);
    assert!(config.do_classes.is_empty());
    assert!(config.kv_bindings.is_empty());
    assert!(config.d1_bindings.is_empty());
    assert!(config.r2_bindings.is_empty());
    assert!(config.queue_bindings.is_empty());
    assert!(config.workflow_bindings.is_empty());

    let runtime = StatelessRuntime::start(
        Arc::new(WorkerConfig::new(config)),
        Arc::from("base-worker-bridge-node"),
        Arc::from("base-worker-bridge-region"),
    )
    .expect("celld loads the Base Worker ES module artifact");
    let response = runtime
        .fetch(
            "https://base.test/bridge".to_string(),
            "GET".to_string(),
            RequestBody::from(Vec::new()),
            Vec::new(),
            None,
        )
        .await
        .expect("celld dispatches a real request to the Base Worker artifact");

    assert_eq!(response.status, 200);
    assert!(response.headers.iter().any(|(name, value)| {
        name.eq_ignore_ascii_case("content-type") && value.starts_with("application/json")
    }));
    assert_eq!(
        String::from_utf8(response.body).expect("response JSON is UTF-8"),
        r#"{"message":"Hello from Base Worker","path":"/bridge"}"#
    );
}

#[test]
fn invalid_javascript_artifact_is_rejected_by_the_existing_celld_host() {
    init_v8();
    let source = include_str!("fixtures/base-worker/invalid.js").to_string();
    let error = match Worker::load_config(Arc::new(WorkerConfig::new(options(source)))) {
        Ok(_) => panic!("invalid JavaScript must not compile as a Worker artifact"),
        Err(error) => error,
    };
    assert!(
        !error.to_string().is_empty(),
        "the host returns a compilation diagnostic"
    );
}
